#!/usr/bin/env python3
"""Generate one CUPS PPD per model in models/ivec_models.json.

usage: generate_ivec_ppd.py models/ivec_models.json OUTDIR
"""
import json
import os
import re
import sys

HEADER = '''*PPD-Adobe: "4.3"
*% model-id: {id}
*% Canon IVEC open driver - generated by generate_ivec_ppd.py, do not edit.
*% SPDX-License-Identifier: GPL-3.0-or-later
*FormatVersion: "4.3"
*FileVersion: "{version}"
*LanguageVersion: English
*LanguageEncoding: ISOLatin1
*PCFileName: "{pcfile}"
*Manufacturer: "Canon"
*Product: "({product})"
*ModelName: "Canon {model}"
*ShortNickName: "Canon {model}"
*NickName: "Canon {model} - IVEC open driver"
*1284DeviceID: "{device_id}"
*PSVersion: "(3010.000) 0"
*LanguageLevel: "3"
*ColorDevice: {color}
*DefaultColorSpace: RGB
*FileSystem: False
*Throughput: "1"
*LandscapeOrientation: Plus90
*TTRasterizer: Type42
*cupsVersion: 2.4
*cupsManualCopies: True
*cupsFilter: "application/vnd.cups-raster 0 rastertocanonivec"
*cupsFilter: "application/vnd.cups-command 0 cmdtocanonivec"
*cupsCommands: "{commands}"
*cupsLanguages: "en"
*cnivecProtocol: "{protocol}"
*cnivecDateTime: "{datetime}"
'''


def ascii(s):
    return s.encode('ascii', 'replace').decode().replace('"', "'")


def fmt(v):
    return ('%.2f' % v).rstrip('0').rstrip('.')


def device_id(raw):
    """Keep only the fields CUPS uses for matching; PPD lines max out at 255 chars."""
    fields = dict(f.split(':', 1) for f in raw.split(';') if ':' in f)
    keep = [k for k in ('MFG', 'CMD', 'MDL', 'CLS', 'DES') if k in fields]
    while True:
        out = ''.join(f'{k}:{fields[k]};' for k in keep)
        if len(out) < 220 or not keep:
            return out
        keep.pop()


def commands(m):
    cmds = ['Clean', 'PrintSelfTestPage']
    tp = m['maint'].get('TestPrint', {})
    if m['maint_style'] == 'ivec' and any(t.endswith('registration') or t == 'regi_check' for t in tp):
        cmds.append('PrintAlignmentPage')
    return ' '.join(cmds)


def ppd_for(m, version):
    out = [HEADER.format(id=m['id'], commands=commands(m),
        version=version, pcfile=('CN' + m['id'][5:])[:8].upper() + '.PPD',
        product=ascii(m['model']), model=ascii(m['model']),
        device_id=ascii(device_id(m['device_id'])), color='True' if m['color'] else 'False',
        protocol=m['protocol'], datetime='True' if m['datetime'] else 'False')]
    out.append(f'*cnivecMaintStyle: "{m["maint_style"]}"\n'
               f'*cnivecMaintDateTime: "{"True" if m["maint_datetime"] else "False"}"\n'
               f'*cnivecMaintHostEnv: "{"True" if m.get("maint_hostenv", True) else "False"}"\n')
    for op, types in m['maint'].items():
        for t, groups in types.items():
            out.append(f'*cnivecMaint {op}.{t}: "{",".join(groups)}"\n')
    if m['duplex']:
        out.append('*cnivecRotateBack: "True"\n')
    if m.get('optimization'):
        out.append('*cnivecOptimization: "True"\n')
    if m['mono_only']:
        out.append('*cnivecColorMode: "monochrome"\n')
    res = m['resolution']

    # Standard ColorModel so every dialog (Chrome, GTK, Qt, LibreOffice) offers
    # colour/grayscale.  Both render RGB; grayscale is signalled to the printer.
    raster = '"<</cupsColorOrder 0/cupsColorSpace 1/cupsBitsPerColor 8>>setpagedevice"'
    gray_default = m.get('default_gray') or m['mono_only'] or not m['color']
    out.append('*OpenUI *ColorModel/Color Mode: PickOne\n*OrderDependency: 10 AnySetup *ColorModel\n'
               f'*DefaultColorModel: {"Gray" if gray_default else "RGB"}\n')
    if m['color'] and not m['mono_only']:
        out.append(f'*ColorModel RGB/Color: {raster}\n')
    out.append(f'*ColorModel Gray/Grayscale: {raster}\n*CloseUI: *ColorModel\n\n')
    out.append('*OpenUI *Resolution/Resolution: PickOne\n*OrderDependency: 10 AnySetup *Resolution\n'
               f'*DefaultResolution: {res}dpi\n'
               f'*Resolution {res}dpi/{res} dpi: "<</HWResolution[{res} {res}]>>setpagedevice"\n'
               '*CloseUI: *Resolution\n\n')

    sizes = m['sizes']
    default = m['default_size'] if any(s['name'] == m['default_size'] for s in sizes) else sizes[0]['name']
    for kw, title in (('PageSize', 'Page Size'), ('PageRegion', 'Page Region')):
        out.append(f'*OpenUI *{kw}/{title}: PickOne\n*OrderDependency: 10 AnySetup *{kw}\n'
                   f'*Default{kw}: {default}\n')
        for s in sizes:
            out.append(f'*{kw} {s["name"]}/{ascii(s["text"])}: '
                       f'"<</PageSize[{fmt(s["w"])} {fmt(s["h"])}]/ImagingBBox null>>setpagedevice"\n')
        out.append(f'*CloseUI: *{kw}\n\n')
    out.append(f'*DefaultImageableArea: {default}\n')
    for s in sizes:
        out.append(f'*ImageableArea {s["name"]}: "{" ".join(fmt(v) for v in s["ia"])}"\n')
    out.append(f'*DefaultPaperDimension: {default}\n')
    for s in sizes:
        out.append(f'*PaperDimension {s["name"]}: "{fmt(s["w"])} {fmt(s["h"])}"\n')
    for s in sizes:
        out.append(f'*cnivecPaperSize {s["name"]}: "{s["pwg"]} {s["print"][0]} {s["print"][1]} '
                   f'{fmt(s["w"])} {fmt(s["h"])}"\n')
    out.append('\n')

    media = m['media']
    dmedia = m['default_media'] if any(x['name'] == m['default_media'] for x in media) else media[0]['name']
    out.append(f'*OpenUI *MediaType/Media Type: PickOne\n*OrderDependency: 10 AnySetup *MediaType\n'
               f'*DefaultMediaType: {dmedia}\n')
    for x in media:
        out.append(f'*MediaType {x["name"]}/{ascii(x["text"])}: "<</MediaType({x["name"]})>>setpagedevice"\n')
    out.append('*CloseUI: *MediaType\n')
    for x in media:
        out.append(f'*cnivecMediaType {x["name"]}: "{x["ivec"]}"\n')
    out.append('\n')

    if m['duplex']:
        out.append('*OpenUI *Duplex/2-Sided Printing: PickOne\n*OrderDependency: 10 AnySetup *Duplex\n'
                   '*DefaultDuplex: None\n'
                   '*Duplex None/Off: "<</Duplex false>>setpagedevice"\n'
                   '*Duplex DuplexNoTumble/Long Edge: "<</Duplex true/Tumble false>>setpagedevice"\n'
                   '*Duplex DuplexTumble/Short Edge: "<</Duplex true/Tumble true>>setpagedevice"\n'
                   '*CloseUI: *Duplex\n\n')

    out.append('*DefaultFont: Courier\n*Font Courier: Standard "(002.004S)" Standard ROM\n')
    return ''.join(out)


def filename(m):
    return 'Canon-' + re.sub(r'[^A-Za-z0-9]+', '_', m['model']).strip('_') + '-ivec.ppd'


def main(db, outdir):
    data = json.load(open(db))
    os.makedirs(outdir, exist_ok=True)
    for m in data['models']:
        with open(os.path.join(outdir, filename(m)), 'w', encoding='ascii') as f:
            f.write(ppd_for(m, data.get('version', '1.0')))
    print(len(data['models']), 'PPDs ->', outdir)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
